// ?findStaticLODLevel@GameLODManager@@QAE?AW4StaticGameLODLevel@@XZ
// partial score=0.85 date=2026-09-27
// cl: /DNDEBUG /MD /EHsc
// Open-BFME: GameLODManager::findStaticLODLevel, retail 0x0007E0F0, 948 bytes.
// readable reference: inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Source/Common/GameLOD.cpp:445
//
// Identity: the lift shipped this body under
// ?getIdealStaticGameDetail@OptionPreferences@@QAEHXZ, which the body refutes -- it
// opens on the GameLODManager's own m_idealDetailLevel (esi+0x1708) and the body is
// the Zero Hour GameLODManager::findStaticLODLevel line for line. The name is proved
// by matched callers in this tree that already call it by that name through ILT
// 0x0002DE02: ScoreScreen_populatePlayerInfo.cpp (0x004E5DF0, matched) and
// ScoreScreen.cpp:886, OptionsMenu.cpp:971.
//
// Name tables read out of the baseline image (the DIR32s the body indexes):
//   0x012A73E4 StaticGameLODNames  VeryLow Low Medium High UltraHigh Custom
//   0x012A7418 CpuNames            XX P3 P4 K7
//   0x012A742C VideoNames          XX GF2 R100 PS11 GFXB GF3 R200 GF4 PS14 PS20 R300 R400
// BFME dropped Zero Hour's Voodoo/TNT tiers, so the chipset this body installs for an
// unknown card (retail's immediate 1) is DC_GEFORCE2, not DC_TNT2.
//
// BFME deltas over the Zero Hour source, all read off the body:
//   - the matched preset also carries a resolution (+0x18/+0x1c) which is published
//     to GlobalData::m_xResolution/m_yResolution and to the "Resolution" preference;
//   - a second preference key, "FixedStaticGameLOD", guarded by m_currentDynamicLOD;
//   - a Windows 2000 downgrade of m_idealDetailLevel by one step.
//
// NOT BYTE-EXACT YET (partial, banked 2026-09-27, probe 155/942 non-reloc bytes,
// 975 compiled vs 942 retail, shape 0.932 after register normalisation). What is
// left, in the order it should be attacked:
//   1. FRAME. Retail `sub esp,0xc4`, ours `0xbc`, and every local sits 4 or 8 bytes
//      low. Retail's slots (relative to the loop's running `preset` pointer at
//      [esp+0x10]) are yres 0x14, an UNUSED dword 0x18, xres 0x1c, numMBRam 0x20,
//      optionPref 0x24, its map 0x2c, osvi 0x38, EH state 0xe0. Ours is numMBRam
//      0x14, xres 0x18, yres 0x1c, optionPref 0x20. Retail's local ORDER is
//      (numMBRam, <4-byte thing>, xres, yres) with the thing never initialised --
//      MSVC 7.1 lays these out in declaration order, and the initialiser order
//      (numMBRam, 800, 600) is unchanged, so the missing local sits between
//      numMBRam and xres. A 4-byte loop-local declared there is the lever;
//      `Int i;` / `Int j;` hoisted out of the for-init is the obvious candidate
//      (retail keeps both in registers, so they need no code, only a slot).
//   2. THE format() ARGUMENT. Retail builds the by-value AsciiString IN the
//      outgoing slot (`mov [esp+0x2c],esp; mov ecx,esp; push "%d %d"; call ctor`)
//      after pushing yres/xres/reserved; ours materialises a temporary first
//      (`push "%d %d"; lea ecx,[slot]; call ctor`) and then pushes the 4-byte
//      OBJECT rather than a pointer to it, which means MSVC 7.1 is treating the
//      parameter as a POD here. A user-declared copy constructor on AsciiString
//      (or dropping the default ctor) is the untried lever; see #1 there too.
//   3. RETAIL'S `if (TheWritableGlobalData)` guards ONLY the two GlobalData
//      stores -- its `je` at +0x2dc lands on the resolution string's zero-init,
//      so the "Resolution" preference is written whether or not GlobalData
//      exists. Already applied; recorded here so it is not "simplified" back.

typedef int Int;
typedef unsigned char Bool;
typedef float Real;
typedef unsigned long DWORD;

#define NULL 0

#define PROFILE_ERROR_LIMIT	0.94f	//fraction of profiled result needed to get a match.

enum StaticGameLODLevel
{
	STATIC_GAME_LOD_UNKNOWN=-1,
	STATIC_GAME_LOD_VERY_LOW,
	STATIC_GAME_LOD_LOW,
	STATIC_GAME_LOD_MEDIUM,
	STATIC_GAME_LOD_HIGH,
	STATIC_GAME_LOD_ULTRA_HIGH,
	STATIC_GAME_LOD_CUSTOM	//make sure this remains last!
};

enum CpuType
{
	XX,	//unknown type
	P3,
	P4,
	K7,
};

// Keep in sync with VideoNames (0x012A742C) in the baseline image.
enum ChipsetType
{
	DC_UNKNOWN,
	DC_GEFORCE2
};

#define MAX_LOD_PRESETS_PER_LEVEL	32

static const char *StaticGameLODNames[]=
{
	"VeryLow",
	"Low",
	"Medium",
	"High",
	"UltraHigh",
	"Custom"
};

// Zero Hour's LODPresetInfo plus the two resolution dwords BFME appends.
struct LODPresetInfo
{
	Int m_cpuType;
	Int m_mhz;
	Real m_cpuPerfIndex;
	Int m_videoType;
	Int m_memory;
	Int m_pad14;
	Int m_xResolution;
	Int m_yResolution;
};

typedef char AssertPresetSize[sizeof(LODPresetInfo) == 0x20 ? 1 : -1];

// The BFME GameLODManager, sized from the offsets the body reads:
// m_lodPresets[i][0] is +0x180 + i*0x400 (the body starts the walk at i=3, +0xD80),
// m_currentStaticLOD/m_currentDynamicLOD +0x16C0/+0x16C4, m_numLevelPresets +0x16F0,
// m_idealDetailLevel +0x1708, m_videoChipType +0x1710, m_cpuType +0x1714, m_numRAM
// +0x1718, m_cpuFreq +0x171C.  The gaps are unread, so they stay padding.
class GameLODManager
{
public:
	StaticGameLODLevel findStaticLODLevel(void);

	const char *getStaticGameLODLevelName(StaticGameLODLevel level)
	{
		return StaticGameLODNames[level];
	}

	unsigned char m_pad000[0x180];
	LODPresetInfo m_lodPresets[STATIC_GAME_LOD_CUSTOM][MAX_LOD_PRESETS_PER_LEVEL];
	unsigned char m_pad1580[0x16c0 - 0x1580];
	StaticGameLODLevel m_currentStaticLOD;
	StaticGameLODLevel m_currentDynamicLOD;
	unsigned char m_pad16c8[0x16f0 - 0x16c8];
	Int m_numLevelPresets[4];		//the walk only ever reads 1..3
	Int m_numBenchProfiles;
	unsigned char m_pad1704[4];
	StaticGameLODLevel m_idealDetailLevel;
	unsigned char m_pad170c[4];
	Int m_videoChipType;
	Int m_cpuType;
	Int m_numRAM;
	Int m_cpuFreq;
};

typedef char AssertMgrSize[sizeof(GameLODManager) == 0x1720 ? 1 : -1];
typedef char AssertEnumSize[sizeof(StaticGameLODLevel) == 4 ? 1 : -1];

extern Bool testMinimumRequirements(Int *videoChipType, Int *cpuType,
	Int *cpuFreq, Int *numRAM, Real *intBenchIndex, Real *floatBenchIndex,
	Real *memBenchIndex);

// 148 bytes, as retail's own dwOSVersionInfoSize immediate proves: five DWORDs and
// szCSDVersion[128], with no wProductType/wReserved tail.
struct BfmeOSVersionInfo
{
	DWORD dwOSVersionInfoSize;
	DWORD dwMajorVersion;
	DWORD dwMinorVersion;
	DWORD dwBuildNumber;
	DWORD dwPlatformId;
	DWORD szCSDVersion[128/4];	//DWORD-typed so the aggregate zero-init is the whole 148 bytes
};

extern "C" __declspec(dllimport) int __stdcall GetVersionExA(BfmeOSVersionInfo *info);

extern "C" void *__cdecl memset(void *destination, int value, unsigned int count);
extern "C" unsigned int __cdecl strlen(const char *text);
#pragma intrinsic(strlen)

struct Rva006C9270GlobalData
{
	unsigned char m_pad[0x2c];
	Int m_xResolution;
	Int m_yResolution;
};

extern Rva006C9270GlobalData *TheWritableGlobalData;

template <class T> class StringBase
{
public:
	StringBase(void) : m_data(0) {}
	~StringBase(void) { releaseBuffer(); }

	StringBase(const T *text);

	Int set(const T *text, Int length);
	void set(const StringBase<T> &other);

protected:
	void releaseBuffer();

	T *m_data;
};

class AsciiString : public StringBase<char>
{
public:
	AsciiString(void) : StringBase<char>() {}
	AsciiString(const char *text) : StringBase<char>(text) {}
	void format(AsciiString format, ...);
};

// The preference map's value type: BFME's MapMetaData derives from the same
// StringBase<char>, which is why both assignment shapes land on StringBase::set.
class MapMetaData : public StringBase<char>
{
public:
	MapMetaData &operator=(const char *s)
	{
		set(s, s ? (Int)strlen(s) : 0);
		return *this;
	}

	MapMetaData &operator=(const AsciiString &other)
	{
		set(other);
		return *this;
	}
};

// STLport's map, spelled so the operator[] mangles to the ledger's name.
namespace _STL
{
template <class T> struct less {};
template <class T> class allocator {};
template <class First, class Second> struct pair {};

template <class Key, class Value, class Compare = less<Key>,
	class Allocator = allocator<pair<const Key, Value> > >
class map
{
public:
	Value &operator[](const Key &key);

private:
	void *m_header;
	unsigned int m_size;
	unsigned int m_allocator;
};
}

typedef _STL::map<AsciiString, MapMetaData, _STL::less<AsciiString>,
	_STL::allocator<_STL::pair<const AsciiString, MapMetaData> > >
	PreferenceMap;

class UserPreferences : public PreferenceMap
{
public:
	virtual ~UserPreferences();
	virtual Bool write(void);
};

class OptionPreferences : public UserPreferences
{
public:
	OptionPreferences(void);
	virtual ~OptionPreferences();
};

/**Function which calculates the recommended LOD level for current hardware
configuration.*/
// ?findStaticLODLevel@GameLODManager@@QAE?AW4StaticGameLODLevel@@XZ
StaticGameLODLevel GameLODManager::findStaticLODLevel(void)
{
	//Check if we have never done the test on current system
	if (m_idealDetailLevel == STATIC_GAME_LOD_UNKNOWN)
	{
		//search all our presets for matching hardware
		// Retail's immediate here is 0, not Zero Hour's STATIC_GAME_LOD_LOW: BFME
		// added VERY_LOW below LOW and made it the "nothing matched" answer, which
		// is also the name the preference below then stores (StaticGameLODNames[0]).
		m_idealDetailLevel = STATIC_GAME_LOD_VERY_LOW;

		//get system configuration - only need video chip type, got rest in ::init().
		testMinimumRequirements(&m_videoChipType,NULL,NULL,NULL,NULL,NULL,NULL);
		if (m_videoChipType == DC_UNKNOWN)
			m_videoChipType = DC_GEFORCE2;	//presume it's at least GeForce2 level

		Int numMBRam=m_numRAM/(1024*1024);
		Int xres=800;
		Int yres=600;

		for (Int i=STATIC_GAME_LOD_HIGH; i >= STATIC_GAME_LOD_LOW; i--)
		{
			LODPresetInfo *preset=&m_lodPresets[i][0];
			for (Int j=0; j<m_numLevelPresets[i]; j++)
			{
				if (	m_cpuType == preset->m_cpuType &&
						((Real)m_cpuFreq/(Real)preset->m_mhz >= PROFILE_ERROR_LIMIT) &&	//make sure we're within 5% or higher
						m_videoChipType >= preset->m_videoType &&
						((Real)numMBRam/(Real)preset->m_memory >= PROFILE_ERROR_LIMIT)
					)
				{	m_idealDetailLevel = (StaticGameLODLevel)i;
					xres = preset->m_xResolution;
					yres = preset->m_yResolution;
					break;
				}

				preset++;	//skip to next preset
			}
			if (m_idealDetailLevel >= i)
				break;	//we already found a higher level than the remaining presets so no need to keep searching.
		}

		//Windows 2000 measured a notch faster than retail's preset table claims.
		BfmeOSVersionInfo osvi;
		memset(&osvi, 0, sizeof(osvi));
		osvi.dwOSVersionInfoSize = sizeof(osvi);
		if (	GetVersionExA(&osvi) &&
			osvi.dwPlatformId == 2 &&
			osvi.dwMajorVersion == 5 &&
			osvi.dwMinorVersion == 0 &&
			m_idealDetailLevel >= STATIC_GAME_LOD_LOW &&
			m_idealDetailLevel <= STATIC_GAME_LOD_ULTRA_HIGH)
		{
			m_idealDetailLevel = (StaticGameLODLevel)(m_idealDetailLevel - 1);
		}

		//Save ideal detail level for future usage
		OptionPreferences optionPref;
		optionPref["IdealStaticGameLOD"] = getStaticGameLODLevelName(m_idealDetailLevel);
		if (m_currentStaticLOD == STATIC_GAME_LOD_UNKNOWN)	//save for future usage.
			optionPref["StaticGameLOD"] = getStaticGameLODLevelName(m_idealDetailLevel);
		if (m_currentDynamicLOD == STATIC_GAME_LOD_UNKNOWN)
			optionPref["FixedStaticGameLOD"] = getStaticGameLODLevelName(m_idealDetailLevel);

		// Retail's `if` guards only the two GlobalData stores: its `je` lands on the
		// resolution string's own zero-init, so the preference is written either way.
		if (TheWritableGlobalData)
		{
			TheWritableGlobalData->m_xResolution = xres;
			TheWritableGlobalData->m_yResolution = yres;
		}
		{
			AsciiString resolution;
			resolution.format(AsciiString("%d %d"), xres, yres);
			optionPref["Resolution"] = resolution;
		}
		optionPref.write();
	}

	return m_idealDetailLevel;
}
